// meta/benchmarks/test_kda_chunked.hip
//
// Correctness test for the chunked WY K3 forward (#70) on gfx942:
//
//   hip::kda_delta_rule_fwd_chunked_with_scratch  vs
//   kda_naive_delta_rule_fwd_cpu                  (the K3 oracle)
//
// The chunked path (kda.hip #L8) computes the SAME per-key-dim recurrence
// as the cooperative kernel but in the affine WY form (grams + explicit
// triangular inverse + U_v/W/T/Opar precompute, then an nc-step serial
// state pass) — the derivation is CPU-verified in
// tests/kernels/attn/test_kda_k3_chunked.cpp (k3_wy_chunked_fwd), which is
// where the CONTRACT below comes from.
//
// CONTRACT (stricter than the cooperative kernel's): k is L2-normalised
// (|M| <= 1 by Cauchy-Schwarz keeps the explicit inverse bounded; with
// unnormalised k it overflows at cs=64), gates in (0,1], beta <= 1,
// chunk_size == 64, S % 64 == 0, D <= 128. Inputs here follow
// test_kda_correct.hip (contractive rgate, normalised keys).
//
// Also checks the caller-owned STATE contract against the cooperative
// kernel with a NONZERO initial state (multi-turn decode shape): both
// entries must consume the same pre-filled state and write the same final
// state back.
//
// Convention (test_kda_correct.hip): max_rel < 2e-2, PASS/FAIL summary on
// the last line.

#include <hip/hip_runtime.h>

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

#include "vkernels/kernels/kda.hpp"

#define CK(e, m)                                                       \
  do {                                                                 \
    hipError_t r = (e);                                                \
    if (r != hipSuccess) {                                             \
      std::fprintf(stderr, "%s: %s\n", m, hipGetErrorString(r));       \
      std::exit(1);                                                    \
    }                                                                  \
  } while (0)

namespace {

float rnd(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13;
  x *= 0x5bd1e995u;
  x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f;  // [-1, 1)
}

// Contractive forget gate in (0.05, 1.0) — the production regime
// (test_kda_correct.hip's rgate).
float rgate(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13; x *= 0x5bd1e995u; x ^= x >> 15;
  return 0.05f + 0.95f * (float)(x % 100000u) / 100000.0f;
}

void normalize_keys(std::vector<float>& k, int B, int H, int S, int D) {
  for (int x = 0; x < B * H * S; ++x) {
    float* kk = k.data() + (size_t)x * D;
    float norm = 0.0f;
    for (int d = 0; d < D; ++d) norm += kk[d] * kk[d];
    norm = 1.0f / std::sqrt(norm + 1e-12f);
    for (int d = 0; d < D; ++d) kk[d] *= norm;
  }
}

struct Stats { double max_abs, max_rel; };

Stats cmp(const std::vector<float>& got, const std::vector<float>& ref) {
  Stats s{0.0, 0.0};
  for (size_t i = 0; i < got.size(); ++i) {
    double e = std::fabs((double)got[i] - ref[i]);
    if (e > s.max_abs) s.max_abs = e;
    double d = std::fmax(std::fabs((double)ref[i]), 1.0);
    if (e / d > s.max_rel) s.max_rel = e / d;
  }
  return s;
}

}  // namespace

int main() {
  hipDeviceProp_t p;
  CK(hipGetDeviceProperties(&p, 0), "props");
  std::printf("GPU: %s (arch=%s)\n", p.name, p.gcnArchName);

  int fails = 0, passes = 0;
  const float THRESH = 2e-2f;
  constexpr int CS = 64;

  // ---------------------------------------------------------------------
  // (1) chunked vs the CPU oracle at zero initial state, all D templates,
  //     multi-chunk and multi-(b,h) shapes.
  // ---------------------------------------------------------------------
  {
    struct Cfg { int B, H, S, D; };
    const Cfg cfgs[] = {
        {1, 1, 64, 16},     {1, 1, 64, 32},      {1, 1, 64, 64},
        {1, 1, 64, 128},    {1, 16, 64, 64},     {2, 1, 128, 128},
        {1, 1, 512, 64},    {1, 1, 512, 128},    {1, 8, 512, 128},
        {1, 128, 512, 128},
    };
    std::printf("--- kda_delta_rule_fwd_chunked vs naive oracle ---\n");
    for (const auto& c : cfgs) {
      const size_t m = (size_t)c.B * c.H * c.S * c.D;
      const size_t ng = (size_t)c.B * c.H * c.S;
      std::vector<float> q(m), k(m), v(m), g(ng * c.D), beta(ng);
      for (size_t i = 0; i < m; ++i) {
        q[i] = rnd(1, (int)i); k[i] = rnd(2, (int)i); v[i] = rnd(3, (int)i);
      }
      for (size_t i = 0; i < g.size(); ++i) g[i] = rgate(4, (int)i);
      for (size_t i = 0; i < beta.size(); ++i) beta[i] = rgate(5, (int)i);
      normalize_keys(k, c.B, c.H, c.S, c.D);

      std::vector<float> ref(m, 0.0f), host(m, 0.0f);
      kda_naive_delta_rule_fwd_cpu(q.data(), k.data(), v.data(), g.data(),
                                   beta.data(), ref.data(),
                                   c.B, c.H, c.S, c.D);

      float *dq, *dk, *dv, *dg, *db, *dstate, *dout, *dscratch;
      CK(hipMalloc(&dq, m * 4), "aq");
      CK(hipMalloc(&dk, m * 4), "ak");
      CK(hipMalloc(&dv, m * 4), "av");
      CK(hipMalloc(&dg, g.size() * 4), "ag");
      CK(hipMalloc(&db, ng * 4), "ab");
      CK(hipMalloc(&dstate, (size_t)c.B * c.H * c.D * c.D * 4), "ast");
      CK(hipMalloc(&dout, m * 4), "ao");
      const size_t sf = vkernels::kernels::hip::kda_chunked_scratch_floats(
          c.B, c.H, c.S, c.D);
      CK(hipMalloc(&dscratch, sf * 4), "asc");
      CK(hipMemcpy(dq, q.data(), m * 4, hipMemcpyHostToDevice), "cq");
      CK(hipMemcpy(dk, k.data(), m * 4, hipMemcpyHostToDevice), "ck");
      CK(hipMemcpy(dv, v.data(), m * 4, hipMemcpyHostToDevice), "cv");
      CK(hipMemcpy(dg, g.data(), g.size() * 4, hipMemcpyHostToDevice), "cg");
      CK(hipMemcpy(db, beta.data(), ng * 4, hipMemcpyHostToDevice), "cb");
      CK(hipMemset(dstate, 0, (size_t)c.B * c.H * c.D * c.D * 4), "zst");

      vkernels::kernels::hip::kda_delta_rule_fwd_chunked_with_scratch(
          dq, dk, dv, dg, db, dstate, dout, dscratch,
          c.B, c.H, c.S, c.D, CS);
      CK(hipDeviceSynchronize(), "sync");
      CK(hipMemcpy(host.data(), dout, m * 4, hipMemcpyDeviceToHost), "co");

      auto st = cmp(host, ref);
      bool ok = st.max_rel < THRESH;
      std::printf("  B=%d H=%-3d S=%-3d D=%-3d  "
                  "max_abs=%.4f max_rel=%.6f  %s\n",
                  c.B, c.H, c.S, c.D, st.max_abs, st.max_rel,
                  ok ? "PASS" : "FAIL");
      ok ? ++passes : ++fails;
      fflush(stdout);
      hipFree(dq); hipFree(dk); hipFree(dv); hipFree(dg); hipFree(db);
      hipFree(dstate); hipFree(dout); hipFree(dscratch);
    }
  }

  // ---------------------------------------------------------------------
  // (2) nonzero initial state: chunked vs the cooperative kernel — both
  //     consume the same pre-filled state (multi-turn decode) and must
  //     produce the same outputs AND write back the same final state.
  // ---------------------------------------------------------------------
  {
    const int B = 2, H = 3, S = 128, D = 64;
    const size_t m = (size_t)B * H * S * D;
    const size_t ng = (size_t)B * H * S;
    const size_t ns = (size_t)B * H * D * D;
    std::vector<float> q(m), k(m), v(m), g(ng * D), beta(ng),
        init(ns), outC(m, 0.f), outN(m, 0.f), stC(ns, 0.f), stN(ns, 0.f);
    for (size_t i = 0; i < m; ++i) {
      q[i] = rnd(1, (int)i); k[i] = rnd(2, (int)i); v[i] = rnd(3, (int)i);
    }
    for (size_t i = 0; i < g.size(); ++i) g[i] = rgate(4, (int)i);
    for (size_t i = 0; i < beta.size(); ++i) beta[i] = rgate(5, (int)i);
    for (size_t i = 0; i < ns; ++i) init[i] = rnd(6, (int)i) * 0.5f;
    normalize_keys(k, B, H, S, D);

    float *dq, *dk, *dv, *dg, *db, *dstC, *dstN, *doutC, *doutN, *dscratch;
    CK(hipMalloc(&dq, m * 4), "aq");
    CK(hipMalloc(&dk, m * 4), "ak");
    CK(hipMalloc(&dv, m * 4), "av");
    CK(hipMalloc(&dg, g.size() * 4), "ag");
    CK(hipMalloc(&db, ng * 4), "ab");
    CK(hipMalloc(&dstC, ns * 4), "ast1");
    CK(hipMalloc(&dstN, ns * 4), "ast2");
    CK(hipMalloc(&doutC, m * 4), "ao1");
    CK(hipMalloc(&doutN, m * 4), "ao2");
    const size_t sf = vkernels::kernels::hip::kda_chunked_scratch_floats(
        B, H, S, D);
    CK(hipMalloc(&dscratch, sf * 4), "asc");
    CK(hipMemcpy(dq, q.data(), m * 4, hipMemcpyHostToDevice), "cq");
    CK(hipMemcpy(dk, k.data(), m * 4, hipMemcpyHostToDevice), "ck");
    CK(hipMemcpy(dv, v.data(), m * 4, hipMemcpyHostToDevice), "cv");
    CK(hipMemcpy(dg, g.data(), g.size() * 4, hipMemcpyHostToDevice), "cg");
    CK(hipMemcpy(db, beta.data(), ng * 4, hipMemcpyHostToDevice), "cb");

    std::printf("--- nonzero initial state: chunked vs cooperative ---\n");
    for (int rep = 0; rep < 2; ++rep) {   // both orders, same inputs
      CK(hipMemcpy(dstC, init.data(), ns * 4, hipMemcpyHostToDevice), "cst1");
      CK(hipMemcpy(dstN, init.data(), ns * 4, hipMemcpyHostToDevice), "cst2");
      vkernels::kernels::hip::kda_delta_rule_fwd_with_scratch(
          dq, dk, dv, dg, db, dstN, doutN, B, H, S, D);
      vkernels::kernels::hip::kda_delta_rule_fwd_chunked_with_scratch(
          dq, dk, dv, dg, db, dstC, doutC, dscratch, B, H, S, D, CS);
      CK(hipDeviceSynchronize(), "sync");
      CK(hipMemcpy(outC.data(), doutC, m * 4, hipMemcpyDeviceToHost), "co1");
      CK(hipMemcpy(outN.data(), doutN, m * 4, hipMemcpyDeviceToHost), "co2");
      CK(hipMemcpy(stC.data(), dstC, ns * 4, hipMemcpyDeviceToHost), "cs1");
      CK(hipMemcpy(stN.data(), dstN, ns * 4, hipMemcpyDeviceToHost), "cs2");
      auto so = cmp(outC, outN);
      auto ss = cmp(stC, stN);
      bool ok = so.max_rel < THRESH && ss.max_rel < THRESH;
      std::printf("  rep=%d  out: max_abs=%.4f max_rel=%.6f   "
                  "final state: max_abs=%.4f max_rel=%.6f  %s\n",
                  rep, so.max_abs, so.max_rel, ss.max_abs, ss.max_rel,
                  ok ? "PASS" : "FAIL");
      ok ? ++passes : ++fails;
      fflush(stdout);
    }
    hipFree(dq); hipFree(dk); hipFree(dv); hipFree(dg); hipFree(db);
    hipFree(dstC); hipFree(dstN); hipFree(doutC); hipFree(doutN);
    hipFree(dscratch);
  }

  std::printf("\n%s (%d/%d PASS)\n", fails ? "FAIL" : "PASS",
              passes, passes + fails);
  return fails ? 1 : 0;
}

// meta/benchmarks/bench_kda_chunked.hip
//
// A/B micro-benchmark (#70): the committed cooperative per-token forward
// (kda_delta_rule_fwd_with_scratch) vs the chunked WY forward
// (kda_delta_rule_fwd_chunked_with_scratch) on gfx942, same inputs, same
// event timing (both entries hipDeviceSynchronize internally, like
// bench_kda). k is L2-normalised (the chunked contract; the coop kernel
// accepts it too — bench_kda normalises as well). State is re-zeroed every
// timed iteration so each sample is identical.
//
// USAGE
//   bench_kda_chunked H S D    one config: prints
//     "H=%d S=%d D=%d coop=%.1fus chunked=%.1fus speedup=%.2fx"
//   bench_kda_chunked          sweep H in {1,8,16,32,64,128} at S=512 D=128
//
// Built only with VKERNELS_HAS_HIP + VKERNELS_BUILD_BENCHMARKS.

#include <hip/hip_runtime.h>

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <functional>
#include <vector>

#include "vkernels/kernels/kda.hpp"

#define CK(e, m)                                                          \
  do {                                                                    \
    hipError_t r = (e);                                                   \
    if (r != hipSuccess) {                                                \
      std::fprintf(stderr, "%s: %s\n", m, hipGetErrorString(r));          \
      std::exit(1);                                                       \
    }                                                                     \
  } while (0)

namespace {

struct BenchResult { double min_us, median_us, mean_us; };

static BenchResult bench_us(const std::function<void()>& launch,
                            hipEvent_t start, hipEvent_t stop,
                            int warmup = 5, int max_iters = 500) {
  (void)hipDeviceSynchronize();
  for (int i = 0; i < warmup; ++i) launch();
  std::vector<float> times;
  int iters = 20;
  while (iters <= max_iters) {
    times.clear();
    for (int i = 0; i < iters; ++i) {
      hipEventRecord(start);
      launch();
      hipEventRecord(stop);
      hipEventSynchronize(stop);
      float ms = 0;
      hipEventElapsedTime(&ms, start, stop);
      // ROCm 6.3 event quirk: rare zero-elapsed samples (see bench_kda).
      if (ms <= 0.0f) continue;
      times.push_back(ms * 1000.0f);
    }
    const int n = (int)times.size();
    if (n == 0) { iters *= 2; continue; }
    double sum = 0;
    for (double t : times) sum += t;
    double mean = sum / n;
    double sum2 = 0;
    for (double t : times) sum2 += t * t;
    double stddev = std::sqrt(std::max(0.0, sum2 / n - mean * mean));
    if ((mean > 0 && stddev / mean < 0.03) || iters >= max_iters) {
      std::sort(times.begin(), times.end());
      return {times[0], times[n / 2], mean};
    }
    iters *= 2;
  }
  return {};
}

static float rnd(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13; x *= 0x5bd1e995u; x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f;  // [-1, 1)
}

static float rgate(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13; x *= 0x5bd1e995u; x ^= x >> 15;
  return 0.05f + 0.95f * (float)(x % 100000u) / 100000.0f;
}

// One A/B config: allocates, normalises k (chunked contract), times BOTH
// entries on identical inputs (state re-zeroed per sample), prints one line.
void bench_ab(hipEvent_t start, hipEvent_t stop, int B, int H, int S, int D) {
  namespace hipk = vkernels::kernels::hip;
  const size_t m = (size_t)B * H * S * D;
  const size_t ng = (size_t)B * H * S;
  const size_t nstate = (size_t)B * H * D * D;
  std::vector<float> q(m), k(m), v(m), g(ng * D), beta(ng);
  for (size_t i = 0; i < m; ++i) {
    q[i] = rnd(1, (int)i); k[i] = rnd(2, (int)i); v[i] = rnd(3, (int)i);
  }
  for (size_t i = 0; i < g.size(); ++i) g[i] = rgate(4, (int)i);
  for (size_t i = 0; i < beta.size(); ++i) beta[i] = rgate(5, (int)i);
  for (int x = 0; x < B * H * S; ++x) {          // L2-normalise k
    float* kk = k.data() + (size_t)x * D;
    float n = 0.0f;
    for (int d = 0; d < D; ++d) n += kk[d] * kk[d];
    n = 1.0f / std::sqrt(n + 1e-12f);
    for (int d = 0; d < D; ++d) kk[d] *= n;
  }

  float *dq, *dk, *dv, *dg, *db, *dstate, *dout, *dscratch;
  CK(hipMalloc(&dq, m * 4), "aq");
  CK(hipMalloc(&dk, m * 4), "ak");
  CK(hipMalloc(&dv, m * 4), "av");
  CK(hipMalloc(&dg, g.size() * 4), "ag");
  CK(hipMalloc(&db, ng * 4), "ab");
  CK(hipMalloc(&dstate, nstate * 4), "ast");
  CK(hipMalloc(&dout, m * 4), "ao");
  const size_t sf = hipk::kda_chunked_scratch_floats(B, H, S, D);
  CK(hipMalloc(&dscratch, sf * 4), "asc");
  CK(hipMemcpy(dq, q.data(), m * 4, hipMemcpyHostToDevice), "cq");
  CK(hipMemcpy(dk, k.data(), m * 4, hipMemcpyHostToDevice), "ck");
  CK(hipMemcpy(dv, v.data(), m * 4, hipMemcpyHostToDevice), "cv");
  CK(hipMemcpy(dg, g.data(), g.size() * 4, hipMemcpyHostToDevice), "cg");
  CK(hipMemcpy(db, beta.data(), ng * 4, hipMemcpyHostToDevice), "cb");

  // Watchdog-aware iteration budget (beverin faults ~0.3-0.7 s of
  // continuous default-stream kernel time; see bench_kda). The coop side
  // is the long one; chunked is expected faster.
  const bool long_k = (S >= 512);
  auto Lc = [&] {   // cooperative (committed baseline)
    hipMemsetAsync(dstate, 0, nstate * 4, 0);
    hipk::kda_delta_rule_fwd_with_scratch(dq, dk, dv, dg, db, dstate, dout,
                                          B, H, S, D);
  };
  auto Lw = [&] {   // chunked WY (#70)
    hipMemsetAsync(dstate, 0, nstate * 4, 0);
    hipk::kda_delta_rule_fwd_chunked_with_scratch(dq, dk, dv, dg, db, dstate,
                                                  dout, dscratch,
                                                  B, H, S, D, 64);
  };
  const auto rc = long_k ? bench_us(Lc, start, stop, 2, 30)
                         : bench_us(Lc, start, stop, 3, 120);
  const auto rw = long_k ? bench_us(Lw, start, stop, 2, 60)
                         : bench_us(Lw, start, stop, 3, 200);
  const double sp = (rw.median_us > 0) ? rc.median_us / rw.median_us : 0.0;
  std::printf("H=%d S=%d D=%d coop=%.1fus chunked=%.1fus speedup=%.2fx\n",
              H, S, D, rc.median_us, rw.median_us, sp);
  fflush(stdout);

  CK(hipFree(dq), "fq"); CK(hipFree(dk), "fk"); CK(hipFree(dv), "fv");
  CK(hipFree(dg), "fg"); CK(hipFree(db), "fb");
  CK(hipFree(dstate), "fst"); CK(hipFree(dout), "fo");
  CK(hipFree(dscratch), "fsc");
}

}  // namespace

int main(int argc, char** argv) {
  hipDeviceProp_t p;
  CK(hipGetDeviceProperties(&p, 0), "props");
  std::printf("GPU: %s (arch=%s)\n", p.name, p.gcnArchName);

  hipEvent_t start, stop;
  CK(hipEventCreate(&start), "ev1");
  CK(hipEventCreate(&stop), "ev2");

  if (argc == 4) {
    bench_ab(start, stop, 1, std::atoi(argv[1]), std::atoi(argv[2]),
             std::atoi(argv[3]));
  } else {
    for (int H : {1, 8, 16, 32, 64, 128})
      bench_ab(start, stop, 1, H, 512, 128);
    for (int S : {1024, 2048})                 // long-context scaling
      bench_ab(start, stop, 1, 32, S, 128);
  }
  return 0;
}

result.output:
321://  #L8 chunked WY forward (#70) — the inter-chunk parallelism lever.
// critical path drops from S token steps (4 barriers each) to nc chunk
// steps (3 barriers each) of GEMM-shaped cooperative work.
//
// CONTRACT (see the CPU test): k is L2-NORMALISED by the caller (the
// production contract, already assumed by bench_kda) so |M| <= 1 by
// Cauchy-Schwarz and the explicit Ainv stays bounded; gates in (0,1],
// beta <= 1. Every exp() argument is <= 0, so every gate factor is in
// (0,1]: no overflow, graceful underflow. S % 64 == 0, D in {16,32,64,128}.
// ===========================================================================
static constexpr int kCs = 64;    // WY chunk size (must divide S)

// ---- (1) per-key-dim within-chunk inclusive log-cumsum -------------------
__global__ void kda_k3_cumsum_kernel(const float* __restrict__ g,
                                     float* __restrict__ L,
                                     int nc, int S, int D) {
  const int bh = blockIdx.x;
  const int c  = blockIdx.y;
  const int kk = threadIdx.x;          // one key-dim per thread
  if (kk >= D) return;
  const size_t base  = ((size_t)bh * nc + c) * kCs * D;
  const size_t gbase = ((size_t)bh * S + (size_t)c * kCs) * D;
  float acc = 0.0f;
  for (int t = 0; t < kCs; ++t) {
    const float gg = g[gbase + (size_t)t * D + kk];
    acc += (gg <= 0.0f) ? -1.0e9f : logf(gg);   // log(0) clamp (kda.cpp)
    L[base + (size_t)t * D + kk] = acc;
  }
}

// ---- (2) chunk-local artifacts (grams -> Ainv -> U_v/W/T/Opar) -----------

// ---- (2) chunk-local artifacts (grams -> Ainv -> U_v/W/T/Opar) -----------
template <int D>
__global__ void kda_k3_local_kernel(
    const float* __restrict__ q, const float* __restrict__ k,
    const float* __restrict__ v, const float* __restrict__ beta,
    const float* __restrict__ L,
    float* __restrict__ Kgw, float* __restrict__ Qgw,
    float* __restrict__ Kgb, float* __restrict__ diagG,
    float* __restrict__ U_v, float* __restrict__ W,
    float* __restrict__ T, float* __restrict__ Opar,
    int nc, int S) {
  const int bh = blockIdx.x, c = blockIdx.y, tid = threadIdx.x;
  const int t0 = c * kCs;
  const size_t tok = (size_t)bh * S + t0;              // first chunk token
  const size_t lb  = ((size_t)bh * nc + c) * kCs * D;  // per-chunk base

  __shared__ float sM[kCs * kCs];   // M -> Ainv (in place, upper stays 0)
  __shared__ float sN[kCs * kCs];   // N (beta folded, upper stays 0)
  __shared__ float sTMP[3 * 256];   // off-diagonal inverse X tiles

  // zero the strict-upper triangles (GEMMs below read full rows)
  for (int i = tid; i < kCs * kCs; i += kTh) { sM[i] = 0.0f; sN[i] = 0.0f; }
  __syncthreads();

  // phase 0: gated operands (elementwise; L ready from kernel 1)
  for (int i = tid; i < kCs * D; i += kTh) {
    const int t = i / D, e = i % D;
    const float lt   = L[lb + (size_t)t * D + e];
    const float lend = L[lb + (size_t)(kCs - 1) * D + e];
    const float e0 = expf(lt), ee = expf(lend - lt);
    Kgw[lb + i] = e0 * k[(tok + t) * D + e];
    Qgw[lb + i] = e0 * q[(tok + t) * D + e];
    Kgb[lb + i] = beta[tok + t] * ee * k[(tok + t) * D + e];
  }
  for (int e = tid; e < D; e += kTh)
    diagG[((size_t)bh * nc + c) * D + e] =
        expf(L[lb + (size_t)(kCs - 1) * D + e]);

  // phase 1: gate-weighted grams, one thread per (t,j) pair, j <= t
  for (int p = tid; p < kCs * (kCs + 1) / 2; p += kTh) {
    int t = 0, rem = p;
    while (rem > t) { rem -= t + 1; ++t; }
    const int j = rem;
    const float* kj = k + (tok + j) * D;
    const float* kt = k + (tok + t) * D;
    const float* qt = q + (tok + t) * D;
    const float* Lj = L + lb + (size_t)j * D;
    const float* Lt = L + lb + (size_t)t * D;
    float mk = 0.0f, nk = 0.0f;
    for (int e = 0; e < D; ++e) {
      const float gw = expf(Lt[e] - Lj[e]);   // G_{j+1,t}[k] <= 1
      mk += gw * kj[e] * kt[e];
      nk += gw * kj[e] * qt[e];
    }
    const float bj = beta[tok + j];
    sN[(size_t)t * kCs + j] = bj * nk;
    if (j < t) sM[(size_t)t * kCs + j] = bj * mk;
  }
  __syncthreads();

  // phase 2a: invert the four 16x16 diagonal blocks of A = I + M.
  // One warp per block, lane = column; the whole column lives in the
  // lane's registers so the forward substitution is barrier-free.
  {
    const int w = tid / 32;
    if (w < 4) {
      const int lane = tid % 32;
      if (lane < 16) {
        const int j = lane, br = w * 16;
        float col[16];
        for (int i = j; i < 16; ++i) {
          float x = (i == j) ? 1.0f : 0.0f;
          const float* arow = sM + (size_t)(br + i) * kCs + br;
          for (int l = j; l < i; ++l) x -= arow[l] * col[l];
          col[i] = x;
        }
        for (int i = j; i < 16; ++i)
          sM[(size_t)(br + i) * kCs + br + j] = col[i];
      }
    }
  }
  __syncthreads();

  // phase 2b: off-diagonal inverse blocks, level by level:
  //   Ainv[r][s] = -Ainv[r][r] @ ( sum_{m=s..r-1} M[r][m] @ Ainv[m][s] )
  // Level r only reads M blocks of row r (never overwritten) and Ainv
  // blocks finalized at earlier levels, so two barrier rounds per level
  // suffice: (a) X tiles into sTMP, (b) the -Ainv[r][r] @ X product back
  // into sM block (r,s) — which destroys M[r][s], unused from here on.
  for (int r = 1; r < 4; ++r) {
    for (int s = 0; s < r; ++s)
      for (int cell = tid; cell < 256; cell += kTh) {
        const int i = cell / 16, jj = cell % 16;
        float x = 0.0f;
        for (int m = s; m < r; ++m)
          for (int l = 0; l < 16; ++l)
            x += sM[(size_t)(r * 16 + i) * kCs + m * 16 + l] *
                 sM[(size_t)(m * 16 + l) * kCs + s * 16 + jj];
        sTMP[s * 256 + cell] = x;
      }
    __syncthreads();
    for (int s = 0; s < r; ++s)
      for (int cell = tid; cell < 256; cell += kTh) {
        const int i = cell / 16, jj = cell % 16;
        float x = 0.0f;
        for (int l = 0; l < 16; ++l)
          x += sM[(size_t)(r * 16 + i) * kCs + r * 16 + l] *
               sTMP[s * 256 + l * 16 + jj];
        sM[(size_t)(r * 16 + i) * kCs + s * 16 + jj] = -x;
      }

  // phase 3: U_v = Ainv @ v ; W = Ainv @ Kgw   (dot over j; Ainv row in LDS)
  for (int i = tid; i < kCs * D; i += kTh) {
    const int t = i / D, d = i % D;
    const float* arow = sM + (size_t)t * kCs;
    float sv = 0.0f, sw = 0.0f;
    for (int j = 0; j < kCs; ++j) {
      const float a = arow[j];
      sv += a * v[(tok + j) * D + d];
      sw += a * Kgw[lb + (size_t)j * D + d];
    }
    U_v[lb + i] = sv;
    W[lb + i]  = sw;
  }
  __syncthreads();   // orders the gmem U_v/W writes for phase 4 readers

  // phase 4: T = N @ U_v ; Opar = Qgw - N @ W   (N row in LDS; tril-incl)
  for (int i = tid; i < kCs * D; i += kTh) {
    const int t = i / D, d = i % D;
    const float* nrow = sN + (size_t)t * kCs;
    float st = 0.0f, sp = 0.0f;
    for (int j = 0; j <= t; ++j) {
      const float n = nrow[j];
      st += n * U_v[lb + (size_t)j * D + d];
      sp += n * W[lb + (size_t)j * D + d];
    }
    T[lb + i]    = st;
    Opar[lb + i] = Qgw[lb + i] - sp;
  }
}

// ---- (3) serial state pass: u/o/C per chunk, rowblock-split over v -------
template <int D, int Rb>
__global__ void kda_k3_state_kernel(
    const float* __restrict__ U_v, const float* __restrict__ W,
    const float* __restrict__ T, const float* __restrict__ Opar,
    const float* __restrict__ Kgb, const float* __restrict__ diagG,
    float* __restrict__ state, float* __restrict__ out,
    int nc, int S) {
  const int bh = blockIdx.y;
  const int v0 = blockIdx.x * Rb;      // this block's state rows [v0, v0+Rb)
  const int tid = threadIdx.x;
  const size_t lb0 = (size_t)bh * nc;
  __shared__ float sC[Rb * D];         // C rows v0..v0+Rb (all k)
  __shared__ float sU[kCs * Rb];       // u tile for the current chunk
  float* Cst = state + (size_t)bh * D * D + (size_t)v0 * D;

  for (int i = tid; i < Rb * D; i += kTh) sC[i] = Cst[i];   // initial state
  __syncthreads();

  for (int c = 0; c < nc; ++c) {
    const size_t lb = (lb0 + c) * kCs * D;
    // u = U_v - W C^T      u[t][v] = U_v[t][v] - sum_k W[t][k] C[v][k]
    for (int i = tid; i < kCs * Rb; i += kTh) {
      const int t = i / Rb, vv = i % Rb;
      const float* wrow = W + lb + (size_t)t * D;
      const float* crow = sC + vv * D;
      float s = U_v[lb + (size_t)t * D + v0 + vv];
      for (int e = 0; e < D; ++e) s -= wrow[e] * crow[e];
      sU[i] = s;
    }
    __syncthreads();   // sU complete before o/C read it
    // o = T + Opar C^T    (uses the OLD C = C_{c-1})
    for (int i = tid; i < kCs * Rb; i += kTh) {
      const int t = i / Rb, vv = i % Rb;
      const float* orow = Opar + lb + (size_t)t * D;
      const float* crow = sC + vv * D;
      float s = T[lb + (size_t)t * D + v0 + vv];
      for (int e = 0; e < D; ++e) s += orow[e] * crow[e];
      out[((size_t)bh * S + c * kCs + t) * D + v0 + vv] = s;
    }
    __syncthreads();   // all o readers done with old C before C is updated
    // C = diagG (.) C + Kgb^T u
    //    C[v][k] = diagG[k] C[v][k] + sum_t Kgb[t][k] u[t][v]
    const float* dg = diagG + (lb0 + c) * D;
    for (int i = tid; i < Rb * D; i += kTh) {
      const int vv = i / D, e = i % D;
      float s = dg[e] * sC[i];
      for (int t = 0; t < kCs; ++t)
        s += Kgb[lb + (size_t)t * D + e] * sU[t * Rb + vv];
      sC[i] = s;
    }
    __syncthreads();   // sC updated before the next chunk's u/o read it
  }

  for (int i = tid; i < Rb * D; i += kTh) Cst[i] = sC[i];  // final state
}

// Scratch float count for the chunked path: L, Kgw, Qgw, Kgb, U_v, W, T,
// Opar are [B,H,nc,cs,D] (= B*H*S*D each); diagG is [B,H,nc,D].
std::size_t kda_chunked_scratch_floats(int B, int H, int S, int D) {
  const size_t ncsd = (size_t)B * H * S * D;
  const size_t nc = (size_t)S / kCs;
  return 8ull * ncsd + (size_t)B * H * nc * D;
}

template <int D>
void launch_chunked(const float* q, const float* k, const float* v,
                    const float* g, const float* beta, float* state,
                    float* out, float* scratch, int B, int H, int S) {
  const int nc = S / kCs;
  const size_t ncsd = (size_t)B * H * S * D;      // per-array float count
  float* L    = scratch;
  float* Kgw  = L + ncsd;         float* Qgw = Kgw + ncsd;
  float* Kgb  = Qgw + ncsd;       float* dgG = Kgb + ncsd;
  float* U_v  = dgG + (size_t)B * H * nc * D;
  float* W    = U_v + ncsd;       float* T   = W + ncsd;
  float* Opar = T + ncsd;
  const dim3 gchunk(B * H, nc);
  kda_k3_cumsum_kernel<<<gchunk, kTh>>>(g, L, nc, S, D);
  kda_k3_local_kernel<D><<<gchunk, kTh>>>(q, k, v, beta, L, Kgw, Qgw, Kgb,
                                         dgG, U_v, W, T, Opar, nc, S);
  constexpr int Rb = (D <= 32) ? D : 32;          // state rows per block
  const dim3 gstate(D / Rb, B * H);
  kda_k3_state_kernel<D, Rb><<<gstate, kTh>>>(U_v, W, T, Opar, Kgb, dgG,
                                              state, out, nc, S);
  hipDeviceSynchronize();   // match the cooperative launcher's convention
}
