int gemv_pick_sk(int N, int K) {
  // Fill MI300A's 228 CUs with ~4 blocks each where the segment budget
  // allows, within {1,2,4,8} and divisibility of K/128.
  int sk = (912 * 32 + N - 1) / N;
  if (sk < 1) sk = 1;
  if (sk > 8) sk = 8;
  while (sk > 1 && (K / 128) % sk != 0) sk >>= 1;   // must divide K/128
  return sk;
}

